(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};

  // ① 建卍解项目
  const nameInput = document.querySelector('.tb-card .tb-input');
  if (!nameInput) return JSON.stringify({ error: '新建面板没打开' });
  setV(nameInput, '卍解测试·超声波避障');
  [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
  await sleep(400);
  [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
  await sleep(3800);
  out.opened = document.querySelector('.pj-title')?.textContent || null;
  out.diffBadge = document.querySelector('.pj-diff')?.textContent || null;
  out.hasCodePanel = !!document.querySelector('.pc-wrap');

  // ② 贴代码
  [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
  await sleep(700);
  const inputs = [...document.querySelectorAll('.pc-input')];
  setV(inputs[0], 'avoid.ino');
  setV(inputs[1], '超声波避障主程序');
  setV(document.querySelector('.pc-textarea'), 'void setup() {\n  pinMode(9, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  digitalWrite(9, HIGH);\n  delay(500);\n}\n');
  await sleep(300);
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
  await sleep(2200);
  out.codeFile = document.querySelector('.pc-item-name')?.textContent || null;

  // ③ 导出作品文件
  let captured = null;
  const orig = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { captured = b; return orig(b); };
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('保存作品文件'))?.click();
  for (let i = 0; i < 24 && !captured; i++) await sleep(500);
  URL.createObjectURL = orig;
  out.exported = !!captured;

  // ④ 生成分享页，检查内嵌作品文件里有没有代码
  let shareBlob = null;
  const orig2 = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { shareBlob = b; return orig2(b); };
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('分享作品'))?.click();
  await sleep(1500);
  [...document.querySelectorAll('.sw-btn')].find((b) => b.textContent.includes('生成分享页'))?.click();
  for (let i = 0; i < 20 && !shareBlob; i++) await sleep(500);
  URL.createObjectURL = orig2;
  if (shareBlob) {
    const html = await shareBlob.text();
    const m = html.match(/var ECP = ("[A-Za-z0-9+/=]{100,}"|null);/);
    if (m && m[1] !== 'null') {
      const bin = atob(m[1].slice(1, -1));
      out.shareHasCodeEntry = bin.includes('code.json');
      out.shareHasCodeText = bin.includes('pinMode(9, OUTPUT)');
      out.shareLeak = /sk-[A-Za-z0-9]{6,}|api[_-]?key|ai_config/i.test(bin);
      out.shareZipBytes = bin.length;
    }
  }

  if (!captured) return JSON.stringify(out);
  const buf = new Uint8Array(await captured.arrayBuffer());
  let bin = '';
  const chunk = 0x8000;
  for (let i = 0; i < buf.length; i += chunk) bin += String.fromCharCode(...buf.subarray(i, i + chunk));
  out.bytes = buf.length;
  out.b64 = btoa(bin);
  return JSON.stringify(out);
})()
